VALUES ('zhao-lie', '籍', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '前403年与魏、韩同受周室册封为诸侯，赵国正式立国，定都邯郸，开启战国历史，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵烈侯"}]'::jsonb, '烈侯', NULL, '赵烈侯')
