VALUES ('zhao-r1', '□', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '烈侯之子，武侯。在位十三年，名失考，事迹不详，国势平稳，无力争霸，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵武侯"}]'::jsonb, '武侯', NULL, '赵武侯')
