VALUES ('zhao-r2', '章', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '敬侯，迁都邯郸，赵国势力东移。在位十二年，国势渐起，为后世霸业奠基，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵敬侯"}]'::jsonb, '敬侯', NULL, '赵敬侯')
