VALUES ('zhao-r3', '种', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '成侯，曾与韩魏分晋，俘虏晋君。在位二十五年，国势尚可，无力争霸，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵成侯"}]'::jsonb, '成侯', NULL, '赵成侯')
