VALUES ('zhao-r6', '何', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '武灵王之子，惠文王。杀忠臣肥义，秦赵长平之战惨败，国力大损，国势危急，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵惠文王"}]'::jsonb, '惠文王', NULL, '赵惠文王')
