VALUES ('zhao-r8', '偃', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '悼襄王，在位九年。秦国连破赵国，国势危急，割地求和，濒临灭亡，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/赵悼襄王"}]'::jsonb, '悼襄王', NULL, '赵悼襄王')
